function mRand(v1, v2) {
	const vd = (v2 - v1);
	return floor(v1 + random(vd * 0.3, vd * 0.7))
}
function mFract(v1, v2, f) {
	const vd = (v2 - v1);
	return floor(v1 + vd * f);
}

class Area {
	constructor(pal) {
		this.pal = pal;
		this.objs = [];
		this.bg = random(this.pal);
		const p1 = createVector(0, 0);
		const p2 = createVector(width, 0);
		const p3 = createVector(width, height);
		const p4 = createVector(0, height);
		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});

		// probability to make hotizontal split
		this.prob = height/(width+height)
	}

	split(num = 1) {
		for (let i = 0; i < num; i++) {
			if ((i + frameCount) % 2 === 1) {
				this.divide();
			} else {
				this.divide_chaos();
			}
		}
	}

	divide() {
		const last = random(this.objs); // this.objs[this.objs.length-1]
		let p1 = last.p1.copy();
		let p2 = last.p2.copy();
		let p3 = last.p3.copy();
		let p4 = last.p4.copy();

		const f1 = random(0.3, 0.7);
		const f2 = random(0.3, 0.7);

		if (random() < this.prob) {
			// horizontal split

			p1.y = mFract(p1.y, p4.y, f1);
			last.p4.y = p1.y
			p1.x = mFract(p1.x, p4.x, f1);
			last.p4.x = p1.x

			p2.y = mFract(p2.y, p3.y, f2);
			last.p3.y = p2.y
			p2.x = mFract(p2.x, p3.x, f2);
			last.p3.x = p2.x

		} else {
			// vertical
			p1.x = mFract(p1.x, p2.x, f1);
			last.p2.x = p1.x
			p1.y = mFract(p1.y, p2.y, f1);
			last.p2.y = p1.y

			p4.x = mFract(p3.x, p4.x, f2);
			last.p3.x = p4.x
			p4.y = mFract(p3.y, p4.y, f2);
			last.p3.y = p4.y
		}

		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_chaos() {
		const last = random(this.objs); // this.objs[this.objs.length-1]
		let p1 = last.p1.copy();
		let p2 = last.p2.copy();
		let p3 = last.p3.copy();
		let p4 = last.p4.copy();

		if (random() < this.prob) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = mRand(p2.y, p3.y);
			last.p4.y = p1.y
			last.p3.y = p2.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = mRand(p3.x, p4.x);
			last.p2.x = p1.x
			last.p3.x = p4.x
		}

		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}	

	divide_straight_lines() {
		const last = random(this.objs); // this.objs[this.objs.length-1]
		let p1 = last.p1.copy();
		let p2 = last.p2.copy();
		let p3 = last.p3.copy();
		let p4 = last.p4.copy();

		if (random() < this.prob) {
			// horizontal split
			p1.y = mRand(p1.y, p4.y);
			p2.y = p1.y
			last.p4.y = p1.y
			last.p3.y = p1.y
		} else {
			// vertical
			p1.x = mRand(p1.x, p2.x);
			p4.x = p1.x
			last.p2.x = p1.x
			last.p3.x = p1.x
		}

		const clr = random(this.pal);
		this.objs.push({p1, p2, p3, p4, clr});
	}

	show(other, t) {
