const FG = "white", FGA = "#FFFFFF40", BG = "tan", BGA = "#422B0EC0";
let S, font, fontSze;
let cells;

async function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	describe(`animation of translation between two (mathematically wrong) subdivisions states`);

	font = await loadFont("https://fonts.googleapis.com/css2?family=Bitcount+Prop+Single+Ink:wght@100..900&family=Noto+Sans:ital,wght@0,100..900;1,100..900&family=Sixtyfour:SCAN@-53&display=swap");
	textFont(font);
	textAlign(LEFT, TOP);

	S = max(width, height);
	fontSze = Math.ceil(S / 50);
	fontSze = ~~(fontSze / 8) * 8;
	textSize(fontSze);

	noStroke();

	strokeJoin(ROUND);
	initScene();
}

function initScene() {
	easingFuncs = [easeInOutBack, easeInOutElastic,easeOutBounce];
	easingFunc = random(easingFuncs);

	area1 = initArea(numOfSlpits);
	area2 = initArea(numOfSlpits);

	setNextTrigger();
}

function draw() {
	background(BG);

	// trigger reached?
	if (millis() > timeTrigger) {
		// console.log("" + (millis() > timeTrigger) + ", " + inTransition);
		setNextTrigger();
		if (inTransition) {
			area1 = area2;
			area2 = initArea(numOfSlpits);
			easingFunc = random(easingFuncs);
		}
		inTransition = !inTransition;
	}

	if (inTransition) {
		const t = easingFunc(1 - (timeTrigger - millis()) / (timing[1] * 1000));
		let bg = lerpColor(color(area1.bg), color(area2.bg), t);
		bg.setAlpha(48);
		background(bg);
		area1.show(area2, t);
		// area1.show();

	} else {
		let bg = color(area1.bg);
		bg.setAlpha(48);
		background(bg);
		// just show area1
		area1.show();

	}

	msg(`@epibyte #genuary2630 "Wrong subdivision" Its not a bug, its a feature.    `)
}

function mousePressed() {
	if (mouseButton.left) initScene();
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function msg(txt) {
	push();
	noStroke();
	fill(FG);
	rectMode(CORNER);
	rect(0, 0, width, fontSze + 2)

	txt += "          ";
	const startIdx = ~~(frameCount / 12) % txt.length;

	txt += txt;
	let croppedTxt = "";
	for (let i = startIdx; i < txt.length; i++) croppedTxt += txt[i];

	fill(BGA);
	text(croppedTxt, 0, 1);

	pop();
}

